    "normalizedName": "dumbbell chest fly",
    "aliases": [
      "dumbbell chest fly"
    ],
    "description": "Classic chest isolation exercise emphasizing deep loaded eccentric stretch across pectoral fibers.",
    "instructions": [
      "Lie on flat bench holding dumbbells with neutral palms directly above chest.",
      "Unlock elbows with a fixed 15-degree bend that remains static throughout.",
      "Inhale and lower arms out wide in an arc until a deep chest stretch is reached.",
      "Contract pectorals to pull dumbbells back together along identical arc.",
      "Squeeze chest at top without clattering weights."
    ],
    "coachingCues": [
      "Pretend you are hugging a massive barrel.",
      "Keep elbow angle fixed; do not turn into a press."
    ],
    "commonMistakes": [
      "Lowering dumbbells too deep past active shoulder flexibility.",
      "Bending elbows excessively into a sloppy bench press."
    ],
    "primaryMuscles": [
      "Mid Chest"
    ],
    "secondaryMuscles": [
      "Front Delts"
    ],
