    "aliases": [
      "low-to-high cable fly"
    ],
    "description": "Upward angled cable fly specifically targeting the clavicular head (upper chest) along muscle fiber orientation.",
    "instructions": [
      "Set cable pulleys at bottom position. Grasp handles with palms facing forward.",
      "Step forward into staggered stance, chest proud with slight forward torso tilt.",
      "Drive arms upward and inward along diagonal trajectory.",
      "Bring hands together at upper chest / chin level.",
      "Squeeze upper chest for 1 second, then control back to deep low stretch."
    ],
    "coachingCues": [
      "Scoop upward from hips to chin.",
      "Keep chest elevated throughout."
    ],
    "commonMistakes": [
      "Using swinging body momentum.",
      "Shrugging shoulders into ears at the top."
    ],
