    "externalId": "wger_ex_cable_fly_high_low",
    "name": "High-to-Low Cable Fly",
    "normalizedName": "high-to-low cable fly",
    "aliases": [
      "high-to-low cable fly"
    ],
    "description": "Downward angled cable crossover maximizing adduction forces through the lower sternal pectoral fibers.",
    "instructions": [
      "Set cable pulleys at highest setting. Take handles and stand centered in split stance.",
      "Keep slight forward torso hinge and elbows softly rounded.",
      "Pull handles downward and inward across hips in a wide sweeping motion.",
      "Cross hands slightly at bottom for maximal inner chest contraction.",
      "Slowly allow handles to rise back to high stretch position."
    ],
    "coachingCues": [
      "Lead with knuckles pointing downward.",
      "Think of bringing elbows together across waist."
    ],
    "commonMistakes": [
      "Leaning too far forward turning it into a decline press.",
      "Letting shoulders hunch forward during stretch."
    ],
