    "normalizedName": "pec deck machine fly",
    "aliases": [
      "pec deck machine fly"
    ],
    "description": "Machine fly eliminating wrist and stabilizer demands to deliver pure isolated pectoral tension.",
    "instructions": [
      "Adjust seat so handles or elbow pads align directly with mid-chest level.",
      "Press lower and upper back flat against pad; pin shoulder blades down.",
      "Bring handles together in front of sternum, squeezing pecs hard.",
      "Hold contraction for 1 to 2 seconds.",
      "Return smoothly until chest muscles reach full stretch without weight stack touching."
    ],
    "coachingCues": [
      "Think of driving elbows together, not just hands.",
      "Chest high, shoulders back against pad."
    ],
