    "externalId": "wger_ex_back_extension",
    "name": "Back Extension / Hyperextension",
    "normalizedName": "back extension / hyperextension",
    "aliases": [
      "back extension / hyperextension"
    ],
    "description": "Posterior chain hinge movement targeting erector spinae, gluteus maximus, and hamstrings.",
    "instructions": [
      "Position yourself in 45-degree hyperextension bench with hips just above pad crease.",
      "Cross arms over chest or hold plate.",
      "Hinge forward at waist until hamstrings and lower back reach stretch.",
      "Raise torso back up to align with legs; avoid hyperextending backward past neutral.",
      "Contract glutes and erectors at top for 1 second."
    ],
    "coachingCues": [
      "Stop when torso is in line with legs.",
      "Squeeze glutes hard at top."
    ],
    "commonMistakes": [
      "Excessive backward hyperextension straining lumbar vertebrae.",
      "Jerking violently with neck."
    ],
