    "externalId": "wger_ex_nordic_curl",
    "name": "Nordic Curl",
    "normalizedName": "nordic curl",
    "aliases": [
      "nordic curl"
    ],
    "description": "Premier eccentric knee flexion bodyweight movement delivering unmatched hamstring injury prevention and strength.",
    "instructions": [
      "Kneel on padded surface with ankles locked securely under partner hands, barbell, or specialist bench.",
      "Torso completely erect in straight line from knees to head.",
      "Lower torso forward toward floor as slowly as possible using hamstrings to resist gravity.",
      "Catch yourself with hands on floor when failure is reached.",
      "Push off floor lightly and pull back up to top position."
    ],
    "coachingCues": [
      "Fight the fall for as long as possible.",
      "Do not bend at hips; maintain straight plank line."
    ],
    "commonMistakes": [
      "Bending at waist and sticking butt out.",
      "Dropping immediately without eccentric resistance."
    ],
