    "externalId": "wger_ex_single_leg_hip_thrust",
    "name": "Single-Leg Hip Thrust",
    "normalizedName": "single-leg hip thrust",
    "aliases": [
      "single-leg hip thrust"
    ],
    "description": "Unilateral bench hip thrust fixing left-right glute activation and force imbalances.",
    "instructions": [
      "Rest upper back on bench, one foot planted firmly on floor, opposite knee bent in air at 90 degrees.",
      "Optional: place dumbbell on working hip.",
      "Drive working heel into floor, lifting hips until working thigh aligns with torso.",
      "Lock out glute for 1 second at top.",
      "Lower under control and repeat."
    ],
    "coachingCues": [
      "Keep hips level; do not let non-working hip dip.",
      "Drive through the working heel."
    ],
    "commonMistakes": [
      "Pelvic rotation during rep.",
      "Incomplete hip extension."
    ],
