    "normalizedName": "bird dog",
    "aliases": [
      "bird dog"
    ],
    "description": "Quadruped core and spinal stability drill developing rotary torso control and posterior sling integration.",
    "instructions": [
      "Assume tabletop position on hands and knees with neutral spine.",
      "Reach right arm straight forward and left leg straight back simultaneously.",
      "Hold at parallel height for 2 seconds without shifting hips.",
      "Return under control and switch sides."
    ],
    "coachingCues": [
      "Imagine balancing a cup of water on your lower back.",
      "Reach long through fingertips and heel."
    ],
