    "externalId": "wger_ex_pallof_press",
    "name": "Pallof Press",
    "normalizedName": "pallof press",
    "aliases": [
      "pallof press"
    ],
    "description": "Premier anti-rotation core exercise training the deep abdominal wall to resist rotational shearing forces.",
    "instructions": [
      "Set cable at chest height with D-handle. Stand sideways to machine in athletic quarter squat.",
      "Hold handle with both hands at center of chest.",
      "Press hands straight out in front of chest.",
      "Hold arms extended for 2 to 3 seconds, fiercely resisting the cable pulling you sideways.",
      "Return hands to chest under control."
    ],
    "coachingCues": [
      "Lock hips and shoulders square forward.",
      "Fight the cable with your core; no rotation permitted."
    ],
    "commonMistakes": [
      "Twisting shoulders toward the cable stack.",
      "Leaning away to counterbalance."
    ],
