    "id": "ex_suitcase_carry",
    "externalId": "wger_ex_suitcase_carry",
    "name": "Suitcase Carry",
    "normalizedName": "suitcase carry",
    "aliases": [
      "suitcase carry"
    ],
    "description": "Single-arm loaded carry forcing the contralateral obliques and quadratus lumborum to prevent lateral flexion.",
    "instructions": [
      "Hold a heavy kettlebell or dumbbell in one hand only at your side.",
      "Stand completely upright without leaning toward or away from the weight.",
      "Walk forward in a slow, controlled line.",
      "Maintain perfectly level shoulders throughout walk.",
      "Switch hands and repeat on opposite side."
    ],
    "coachingCues": [
      "Do not lean to compensate; keep torso vertical.",
      "Brace opposite oblique hard."
    ],
    "commonMistakes": [
      "Tilting sideways under load.",
      "Swinging weight into thigh."
    ],
    "primaryMuscles": [
      "Core Abs",
      "Forearms"
    ],
